import { TARGET_RTP } from '../rtp.js';

const values = Array.from({ length: 10 }, (_, i) => i + 1);
const probability = (value) => (value === 10 ? 4 : 1) / 13;
export const BLACKJACK_RETURN = 2.5;
// Generated by scripts/calibrate-blackjack.mjs for independent 52-card draws,
// S17, peek, no split/surrender/insurance, and double on any initial two cards.
export const BLACKJACK_WIN_RETURN = 1.999793523638599;

function add(total, soft, value) {
  total += value === 1 ? 11 : value;
  let aces = Number(soft) + Number(value === 1);
  while (total > 21 && aces) { total -= 10; aces--; }
  return { total, soft: aces > 0 };
}
const isNatural = (a, b) => a === 1 && b === 10 || a === 10 && b === 1;

export function createBlackjackAnalysis(winReturn = BLACKJACK_WIN_RETURN) {
  const dealerCache = new Map();
  function dealer(total, soft) {
    const key = `${total}/${soft}`;
    if (dealerCache.has(key)) return dealerCache.get(key);
    const distribution = Array(6).fill(0); // 17..21, bust
    if (total > 21) distribution[5] = 1;
    else if (total >= 17) distribution[total - 17] = 1;
    else for (const value of values) {
      const next = add(total, soft, value);
      const child = dealer(next.total, next.soft);
      child.forEach((chance, i) => { distribution[i] += probability(value) * chance; });
    }
    dealerCache.set(key, distribution);
    return distribution;
  }
  const tables = new Map();
  function table(up) {
    if (tables.has(up)) return tables.get(up);
    const naturalChance = up === 1 ? 4 / 13 : up === 10 ? 1 / 13 : 0;
    const distribution = Array(6).fill(0);
    for (const hole of values) {
      if (isNatural(up, hole)) continue;
      const first = add(0, false, up);
      const second = add(first.total, first.soft, hole);
      dealer(second.total, second.soft).forEach((chance, i) => { distribution[i] += probability(hole) * chance / (1 - naturalChance); });
    }
    const memo = new Map();
    const stand = (total) => {
      if (total > 21) return 0;
      return distribution.reduce((sum, chance, i) => sum + chance * (i === 5 || total > i + 17 ? winReturn : total === i + 17 ? 1 : 0), 0);
    };
    function best(total, soft, canDouble) {
      if (total > 21) return { payout: 0, stake: 1, action: 'stand' };
      const key = `${total}/${soft}/${canDouble}`;
      if (memo.has(key)) return memo.get(key);
      const options = [{ payout: stand(total), stake: 1, action: 'stand' }];
      if (total < 21) {
        const hit = { payout: 0, stake: 1, action: 'hit' };
        let doublePayout = 0;
        for (const value of values) {
          const next = add(total, soft, value);
          hit.payout += probability(value) * best(next.total, next.soft, false).payout;
          doublePayout += probability(value) * 2 * stand(next.total);
        }
        options.push(hit);
        if (canDouble) options.push({ payout: doublePayout, stake: 2, action: 'double' });
      }
      const selected = options.reduce((a, b) => b.payout - TARGET_RTP * b.stake > a.payout - TARGET_RTP * a.stake ? b : a);
      memo.set(key, selected);
      return selected;
    }
    const result = { naturalChance, best };
    tables.set(up, result);
    return result;
  }
  return {
    recommend(total, soft, up, canDouble = false) { return table(up).best(total, soft, canDouble).action; },
    expected() {
      let payout = 0, stake = 0;
      for (const up of values) for (const a of values) for (const b of values) {
        const weight = probability(up) * probability(a) * probability(b);
        const { naturalChance, best } = table(up);
        if (isNatural(a, b)) {
          payout += weight * (naturalChance + (1 - naturalChance) * BLACKJACK_RETURN);
          stake += weight;
        } else {
          const first = add(0, false, a);
          const hand = add(first.total, first.soft, b);
          const play = best(hand.total, hand.soft, true);
          payout += weight * (1 - naturalChance) * play.payout;
          stake += weight * (naturalChance + (1 - naturalChance) * play.stake);
        }
      }
      return { payout, stake, rtp: payout / stake };
    },
  };
}

let strategy;
export function blackjackRecommendation(cards, up, canDouble) {
  strategy ??= createBlackjackAnalysis();
  let hand = { total: 0, soft: false };
  for (const card of cards) hand = add(hand.total, hand.soft, card.rank === 'A' ? 1 : ['J', 'Q', 'K'].includes(card.rank) ? 10 : Number(card.rank));
  const value = up.rank === 'A' ? 1 : ['J', 'Q', 'K'].includes(up.rank) ? 10 : Number(up.rank);
  return strategy.recommend(hand.total, hand.soft, value, canDouble);
}
